#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <numeric>
#include <cstdlib>

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    int a, b, n;
    iss >> a >> b >> n;

    while (true) {
        long long ax = gcd(a, n);
        if (ax > n) {
            std::cout << 1 << std::endl;
            return 0;
        }
        n -= ax;
        long long bx = gcd(b, n);
        if (bx > n) {
            std::cout << 0 << std::endl;
            return 0;
        }
        n -= bx;
    }
}
