using namespace std;

int gcd(int x, int y) {
    if (x < 0) x = -x;
    if (y < 0) y = -y;
    while (y != 0) {
        int r = x % y;
        x = y;
        y = r;
    }
    return x;
}

int main() {
    string line;
    getline(cin, line);
    istringstream iss(line);
    int a, b, n;
    iss >> a >> b >> n;

    while (true) {
        int ax = gcd(a, n);
        if (ax > n) {
            cout << 1 << endl;
            return 0;
        }
        n -= ax;
        int bx = gcd(b, n);
        if (bx > n) {
            cout << 0 << endl;
            return 0;
        }
        n -= bx;
    }
}
